// ============================================================
//  ScrollToTop
// ============================================================
const HEADER_OFFSET = 96;
const MAX_SCROLL_ATTEMPTS = 20;
const SCROLL_RETRY_DELAY = 50;

function ScrollToTop() {
  const location = useLocation();
  const { pathname, hash, key } = location;

  useEffect(() => {
    if (!hash) {
      window.scrollTo({ top: 0, behavior: 'instant' });
      return;
    }

    const id = hash.replace(/^#/, '');
    if (!id) {
      window.scrollTo({ top: 0, behavior: 'instant' });
      return;
    }

    let cancelled = false;
    let attempts = 0;
    let timer = null;

    const tryScroll = () => {
      if (cancelled) return;

      const el = document.getElementById(id);
      if (el) {
        const top =
          el.getBoundingClientRect().top +
          window.pageYOffset -
          HEADER_OFFSET;
        window.scrollTo({
          top: Math.max(0, top),
          behavior: 'smooth',
        });
        return;
      }

      attempts += 1;
      if (attempts < MAX_SCROLL_ATTEMPTS) {
        timer = setTimeout(tryScroll, SCROLL_RETRY_DELAY);
      }
    };

    const raf = requestAnimationFrame(tryScroll);

    return () => {
      cancelled = true;
      cancelAnimationFrame(raf);
      if (timer) clearTimeout(timer);
    };
  }, [pathname, hash, key]);

  return null;
}

// ============================================================
//  ProtectedRoute / AdminRoute / PublicOnlyRoute
// ============================================================
function ProtectedRoute({ children }) {
  const [isLoggedIn] = useState(() => !!localStorage.getItem('userToken'));
  if (!isLoggedIn) {
    return <Navigate to="/login?next=panel" replace />;
  }
  return children;
}

function AdminRoute({ children }) {
  const [isAdmin, setIsAdmin] = useState(
    () => !!localStorage.getItem('adminToken')
  );

  useEffect(() => {
    const handler = () => setIsAdmin(!!localStorage.getItem('adminToken'));
    window.addEventListener('storage', handler);
    window.addEventListener('adminAuthUpdated', handler);
    return () => {
      window.removeEventListener('storage', handler);
      window.removeEventListener('adminAuthUpdated', handler);
    };
  }, []);

  if (!isAdmin) {
    return <Navigate to="/admin/login" replace />;
  }
  return children;
}

function PublicOnlyRoute({ children }) {
  const [isLoggedIn] = useState(() => !!localStorage.getItem('userToken'));
  if (isLoggedIn) {
    return <Navigate to="/panel" replace />;
  }
  return children;
}

// ============================================================
//  App Content
// ============================================================
function AppContent() {
  return (
    <>
      <ScrollToTop />
      <Suspense fallback={<LoadingFallback />}>
        <Routes>
          {/* Public routes */}
          <Route path="/" element={<UserApp />} />
          <Route path="/cart" element={<Cart />} />

          {/* ✅ Static SEO pages */}
          <Route path="/about" element={<About />} />
          <Route path="/contact" element={<Contact />} />

          {/* ✅ NEW v4.2: Blog routes */}
          <Route path="/blog" element={<BlogList />} />
          <Route path="/blog/:slug" element={<BlogPostPage />} />

          {/* Auth routes */}
          <Route
            path="/login"
            element={
              <PublicOnlyRoute>
                <UserLogin />
              </PublicOnlyRoute>
            }
          />
          <Route
            path="/register"
            element={
              <PublicOnlyRoute>
                <UserRegister />
              </PublicOnlyRoute>
            }
          />

          {/* User panel */}
          <Route
            path="/panel/*"
            element={
              <ProtectedRoute>
                <UserPanel />
              </ProtectedRoute>
            }
          />

          {/* Admin */}
          <Route path="/admin/login" element={<AdminLogin />} />
          <Route
            path="/admin/*"
            element={
              <AdminRoute>
                <AdminApp />
              </AdminRoute>
            }
          />

          {/* 404 */}
          <Route path="*" element={<NotFound />} />
        </Routes>
      </Suspense>
    </>
  );
}

export default function App() {
  return (
    <BrowserRouter>
      <AppContent />
    </BrowserRouter>
  );
}
